#pragma once

#include "CoreMinimal.h"

#include "Containers/ArrayView.h"

struct FElysiumNpcClass;

// The override census (0019 story 5 commit B): one row per live (class, slot) own body of the
// kernel census that the port carries as a C++ override. The rows are generated by
// `uv run elysium research gen_kernel_shape` into `ElysiumNpcKernelOverrideCensus.cpp` (never
// hand-edited) with two compile-time proofs each; `kernel_shape --unported` lists the live rows the
// port does not carry yet, and the two partition the census's live rows. Test support only.
struct FElysiumNpcPortedOverride
{
	// The retail class, the slot and the body the census records.
	const TCHAR* Class = nullptr;
	int32 Slot = 0;
	const TCHAR* Address = nullptr;
	// `rule`, `present` or `mechanism` (`kernel_verdicts.tsv`).
	const TCHAR* Verdict = nullptr;
	// The port class retail's factory builds for `Class`, and the class that declares the override
	// (itself, or the port class of the ancestor whose body `Class` inherits).
	const TCHAR* PortClass = nullptr;
	const TCHAR* DeclaringClass = nullptr;
	// The port's name for the slot, as the override spells it.
	const TCHAR* Method = nullptr;
	// `PortClass::StaticRetailClass`: the census row the port class answers as its identity.
	const FElysiumNpcClass* (*PortRow)() = nullptr;
	// `Method`, with the recorded signature, is declared on `DeclaringClass` itself.
	bool bDeclared = false;
	// `PortClass` derives from (or is) `DeclaringClass`.
	bool bInherits = false;
};

namespace ElysiumNpcKernelOverrideCensus
{
	TArrayView<const FElysiumNpcPortedOverride> Rows();
	// The census's live (class, slot) own-body rows on live classes: `Rows()` plus the
	// `no-override` rows of `kernel_shape --unported`.
	int32 LiveRows();
}
